def enum_table(name: str) -> dict:
    try:
        return REQUIRED_ENUMS[name]
    except KeyError as exc:
        raise KeyError(f"Unknown synthesized enum table: {name}") from exc

def label_value_pairs(name: str, *, hide_none: bool = True) -> list[tuple[str, int | float | str]]:
    table = enum_table(name)
    pairs = []
    for label, value in table.items():
        if hide_none and label.lower() == "none":
            continue
        pairs.append((label, value))
    return pairs
